fn rolling_max(s: &Vec<i8>) -> Option<i8> {
    // Check if the array has at least two elements
    if s.len() < 2 {
        return None;
    }

    // Use a HashSet to store unique values
    let mut unique_values: std::collections::HashSet<i8> = std::collections::HashSet::new();
    
    // Insert all elements into the HashSet to ensure uniqueness
    for &value in s {
        unique_values.insert(value);
    }

    // If there are less than 2 unique values, return None
    if unique_values.len() < 2 {
        return None;
    }

    // Convert the HashSet to a Vec and sort it
    let mut sorted_values: Vec<i8> = unique_values.into_iter().collect();
    sorted_values.sort_unstable();

    // Return the second largest value
    sorted_values.pop(); // Remove the largest
    sorted_values.pop() // Return the second largest
}

